import {
  run,
  type OutputObjectDefinition,
  type RunOptions,
  type RunResult,
} from "@ai-hero/sandcastle";

export interface RunWithExtractionOptions<T> extends Omit<
  RunOptions,
  "output"
> {
  readonly output: OutputObjectDefinition<T>;
  readonly extractionPrompt: string;
  /**
   * Extra attempts after the first if extraction or validation fails. Forwarded
   * to `Output`'s built-in `maxRetries`, which resumes the extraction session
   * and feeds back the error so the agent can re-emit a corrected tag.
   * Default: `2` (three attempts total).
   */
  readonly maxRetries?: number;
}

export async function runWithExtraction<T>(
  options: RunWithExtractionOptions<T>,
): Promise<RunResult & { output: T }> {
  const {
    output,
    extractionPrompt,
    maxRetries = 2,
    ...produceOptions
  } = options;
  const produce = await run(produceOptions);
  const sessionId = produce.iterations.at(-1)?.sessionId;

  if (!sessionId) {
    throw new Error(
      "Cannot extract structured output because the produce run had no session id.",
    );
  }

  const { promptArgs: _promptArgs, ...extractionOptions } = produceOptions;
  const extraction = await run({
    ...extractionOptions,
    name: produceOptions.name ? `${produceOptions.name} (extract)` : undefined,
    promptFile: undefined,
    prompt: extractionPrompt,
    // Extraction ends with the output tag, not `<promise>COMPLETE</promise>`.
    completionSignal: `</${output.tag}>`,
    resumeSession: sessionId,
    output: { ...output, maxRetries },
  });

  return { ...produce, output: extraction.output };
}

/**
 * Per-worker git config isolation.
 *
 * Vitest runs test files in parallel across forked worker processes.
 * Multiple tests call `git config --global` (e.g. to add safe.directory),
 * which writes to the file at GIT_CONFIG_GLOBAL. When all workers share a
 * single file, concurrent writes race on `.gitconfig.lock` and cause
 * intermittent "could not lock config file" failures.
 *
 * This setup file runs inside each worker process (via vitest `setupFiles`),
 * giving every worker its own gitconfig file and eliminating cross-worker
 * lock contention.
 */
import { mkdtempSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const tmpDir = mkdtempSync(join(tmpdir(), "test-gitconfig-worker-"));
const globalConfigPath = join(tmpDir, ".gitconfig");
writeFileSync(
  globalConfigPath,
  "[user]\n\temail = test@test.com\n\tname = Test\n",
);
process.env.GIT_CONFIG_GLOBAL = globalConfigPath;

process.on("exit", () => {
  try {
    rmSync(tmpDir, { recursive: true });
  } catch {
    // best-effort cleanup
  }
});

