import { describe, expect, it } from "vitest";
import { listAgents, getAgent } from "./InitService.js";

describe("Agent registry", () => {
  it("listAgents returns at least claude-code", () => {
    const agents = listAgents();
    expect(agents.some((a) => a.name === "claude-code")).toBe(true);
  });

  it("getAgent returns claude-code entry with expected fields", () => {
    const agent = getAgent("claude-code");
    expect(agent).toBeDefined();
    expect(agent!.name).toBe("claude-code");
    expect(agent!.defaultModel).toBe("claude-opus-4-8");
    expect(agent!.factoryImport).toBe("claudeCode");
    expect(agent!.dockerfileTemplate).toContain("FROM");
  });

  it("getAgent returns undefined for unknown agent", () => {
    expect(getAgent("nonexistent")).toBeUndefined();
  });

  it("listAgents includes pi", () => {
    const agents = listAgents();
    expect(agents.some((a) => a.name === "pi")).toBe(true);
  });

  it("getAgent returns pi entry with expected fields", () => {
    const agent = getAgent("pi");
    expect(agent).toBeDefined();
    expect(agent!.name).toBe("pi");
    expect(agent!.defaultModel).toBe("claude-sonnet-4-6");
    expect(agent!.factoryImport).toBe("pi");
    expect(agent!.dockerfileTemplate).toContain("FROM");
    expect(agent!.dockerfileTemplate).toContain(
      "@mariozechner/pi-coding-agent",
    );
  });

  it("listAgents includes codex", () => {
    const agents = listAgents();
    expect(agents.some((a) => a.name === "codex")).toBe(true);
  });

  it("getAgent returns codex entry with expected fields", () => {
    const agent = getAgent("codex");
    expect(agent).toBeDefined();
    expect(agent!.name).toBe("codex");
    expect(agent!.defaultModel).toBe("gpt-5.4");
    expect(agent!.factoryImport).toBe("codex");
    expect(agent!.dockerfileTemplate).toContain("FROM");
    expect(agent!.dockerfileTemplate).toContain("@openai/codex");
  });

  it("listAgents includes opencode", () => {
    const agents = listAgents();
    expect(agents.some((a) => a.name === "opencode")).toBe(true);
  });

  it("listAgents includes cursor", () => {
    const agents = listAgents();
    expect(agents.some((a) => a.name === "cursor")).toBe(true);
  });

  it("getAgent returns cursor entry with expected fields", () => {
    const agent = getAgent("cursor");
    expect(agent).toBeDefined();
    expect(agent!.name).toBe("cursor");
    expect(agent!.defaultModel).toBe("composer-2");
    expect(agent!.factoryImport).toBe("cursor");
    expect(agent!.dockerfileTemplate).toContain("FROM");
    expect(agent!.dockerfileTemplate).toContain("cursor.com/install");
  });

  it("getAgent returns opencode entry with expected fields", () => {
    const agent = getAgent("opencode");
    expect(agent).toBeDefined();
    expect(agent!.name).toBe("opencode");
    expect(agent!.defaultModel).toBe("opencode/big-pickle");
    expect(agent!.factoryImport).toBe("opencode");
    expect(agent!.dockerfileTemplate).toContain("FROM");
    expect(agent!.dockerfileTemplate).toContain("opencode-ai");
  });

  it("listAgents includes copilot", () => {
    const agents = listAgents();
    expect(agents.some((a) => a.name === "copilot")).toBe(true);
  });

  it("getAgent returns copilot entry with expected fields", () => {
    const agent = getAgent("copilot");
    expect(agent).toBeDefined();
    expect(agent!.name).toBe("copilot");
    expect(agent!.factoryImport).toBe("copilot");
    expect(agent!.dockerfileTemplate).toContain("FROM");
    expect(agent!.dockerfileTemplate).toContain("@github/copilot");
  });
});

import * as sandcastle from "@ai-hero/sandcastle";
import { vercel } from "@ai-hero/sandcastle/sandboxes/vercel";

const claudeInstallHook = {
  command: "curl -fsSL https://claude.ai/install.sh | bash",
};

const ghCliInstallHook = {
  command:
    "curl -fsSL https://cli.github.com/packages/rpm/gh-cli.repo -o /etc/yum.repos.d/gh-cli.repo && dnf install -y gh",
  sudo: true,
};

// /matt-pococks-projects/sandcastle
const { commits, branch } = await sandcastle.run({
  sandbox: vercel({
    token: process.env.VERCEL_OIDC_TOKEN,
    teamId: "matt-pococks-projects",
    projectId: "sandcastle",
  }),
  name: "Test",
  agent: sandcastle.claudeCode("claude-sonnet-4-6"),
  prompt: "Add /foobar to the .gitignore, then commit.",
  hooks: {
    sandbox: {
      onSandboxReady: [
        claudeInstallHook,
        ghCliInstallHook,
        {
          command: "npm install && npm run build",
        },
      ],
    },
  },
});

console.log("Commits:", commits);
console.log("Branch:", branch);

import { exec } from "node:child_process";
import { mkdtemp, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { promisify } from "node:util";
import { Effect } from "effect";
import { describe, expect, it } from "vitest";
import { testIsolated } from "./sandboxes/test-isolated.js";
import { syncIn } from "./syncIn.js";

const execAsync = promisify(exec);

const initRepo = async (dir: string) => {
  await execAsync("git init -b main", { cwd: dir });
  await execAsync('git config user.email "test@test.com"', { cwd: dir });
  await execAsync('git config user.name "Test"', { cwd: dir });
};

const commitFile = async (
  dir: string,
  name: string,
  content: string,
  message: string,
) => {
  await writeFile(join(dir, name), content);
  await execAsync(`git add "${name}"`, { cwd: dir });
  await execAsync(`git commit -m "${message}"`, { cwd: dir });
};

const getHead = async (dir: string) => {
  const { stdout } = await execAsync("git rev-parse HEAD", { cwd: dir });
  return stdout.trim();
};

describe("syncIn", () => {
  it("bundles a repo and clones it into the sandbox — files present", async () => {
    const hostDir = await mkdtemp(join(tmpdir(), "host-"));
    await initRepo(hostDir);
    await commitFile(hostDir, "hello.txt", "hello world", "initial commit");

    const provider = testIsolated();
    const handle = await provider.create({ env: {} });
    try {
      await Effect.runPromise(syncIn(hostDir, handle));

      const result = await handle.exec("cat hello.txt");
      expect(result.stdout.trim()).toBe("hello world");
    } finally {
      await handle.close();
    }
  });

  it("preserves git history after clone from bundle", async () => {
    const hostDir = await mkdtemp(join(tmpdir(), "host-"));
    await initRepo(hostDir);
    await commitFile(hostDir, "a.txt", "a", "first commit");
    await commitFile(hostDir, "b.txt", "b", "second commit");
    await commitFile(hostDir, "c.txt", "c", "third commit");

    const provider = testIsolated();
    const handle = await provider.create({ env: {} });
    try {
      await Effect.runPromise(syncIn(hostDir, handle));

      // Verify HEAD matches
      const sandboxHead = (
        await handle.exec("git rev-parse HEAD")
      ).stdout.trim();
      expect(sandboxHead).toBe(await getHead(hostDir));

      // Verify all 3 commits are present
      const log = (await handle.exec("git log --oneline")).stdout.trim();
      expect(log.split("\n")).toHaveLength(3);

      // Verify all files present
      expect((await handle.exec("cat a.txt")).stdout.trim()).toBe("a");
      expect((await handle.exec("cat b.txt")).stdout.trim()).toBe("b");
      expect((await handle.exec("cat c.txt")).stdout.trim()).toBe("c");
    } finally {
      await handle.close();
    }
  });

  it("works with repos that have unpushed commits (no remote)", async () => {
    const hostDir = await mkdtemp(join(tmpdir(), "host-"));
    await initRepo(hostDir);
    await commitFile(hostDir, "local-only.txt", "no remote", "local commit");

    const provider = testIsolated();
    const handle = await provider.create({ env: {} });
    try {
      await Effect.runPromise(syncIn(hostDir, handle));

      const sandboxHead = (
        await handle.exec("git rev-parse HEAD")
      ).stdout.trim();
      expect(sandboxHead).toBe(await getHead(hostDir));

      const content = (await handle.exec("cat local-only.txt")).stdout.trim();
      expect(content).toBe("no remote");
    } finally {
      await handle.close();
    }
  });

  it("returns the current branch name", async () => {
    const hostDir = await mkdtemp(join(tmpdir(), "host-"));
    await initRepo(hostDir);
    await commitFile(hostDir, "file.txt", "content", "initial");

    const provider = testIsolated();
    const handle = await provider.create({ env: {} });
    try {
      const result = await Effect.runPromise(syncIn(hostDir, handle));
      expect(result.branch).toBe("main");
    } finally {
      await handle.close();
    }
  });

  it("works with a non-main branch", async () => {
    const hostDir = await mkdtemp(join(tmpdir(), "host-"));
    await initRepo(hostDir);
    await commitFile(hostDir, "file.txt", "on main", "initial");
    await execAsync("git checkout -b feature-branch", { cwd: hostDir });
    await commitFile(hostDir, "feature.txt", "feature work", "feature commit");

    const provider = testIsolated();
    const handle = await provider.create({ env: {} });
    try {
      const result = await Effect.runPromise(syncIn(hostDir, handle));
      expect(result.branch).toBe("feature-branch");

      // Feature file should exist
      expect((await handle.exec("cat feature.txt")).stdout.trim()).toBe(
        "feature work",
      );

      // Sandbox should be on the same branch
      const sandboxBranch = (
        await handle.exec("git rev-parse --abbrev-ref HEAD")
      ).stdout.trim();
      expect(sandboxBranch).toBe("feature-branch");
    } finally {
      await handle.close();
    }
  });

  it("only syncs committed state — uncommitted changes are excluded", async () => {
    const hostDir = await mkdtemp(join(tmpdir(), "host-"));
    await initRepo(hostDir);
    await commitFile(hostDir, "committed.txt", "committed", "initial");

    // Add uncommitted changes
    await writeFile(join(hostDir, "committed.txt"), "modified uncommitted");
    await writeFile(join(hostDir, "untracked.txt"), "untracked file");

    const provider = testIsolated();
    const handle = await provider.create({ env: {} });
    try {
      await Effect.runPromise(syncIn(hostDir, handle));

      // Committed content should be the original
      const content = (await handle.exec("cat committed.txt")).stdout.trim();
      expect(content).toBe("committed");

      // Untracked file should not exist
      const ls = (await handle.exec("ls")).stdout;
      expect(ls).not.toContain("untracked.txt");
    } finally {
      await handle.close();
    }
  });
});

import { describe, expect, it } from "vitest";
import { planEffects, TAGS, type Plan, type Tag } from "./batch";

const planFor = (tag: Tag): Plan => ({
  issues: [{ number: 1, tag, duplicate_of: null, comment: "Findings." }],
  patterns: "",
});

const labelFor = (tag: Tag): string | undefined =>
  planEffects(planFor(tag)).flatMap((effect) =>
    effect.kind === "swap-label" ? [effect.to] : [],
  )[0];

const footerFor = (tag: Tag): string | undefined =>
  planEffects(planFor(tag)).flatMap((effect) =>
    effect.kind === "comment" ? [effect.body] : [],
  )[0];

const EXPECTED: Record<Tag, string> = {
  "easy-call": "agent:implement",
  "needs-a-human": "ready-for-human",
  blocked: "agent:blocked",
};

describe("planEffects verdict labels", () => {
  it.each(TAGS)("swaps a %s survivor to its verdict's label", (tag) => {
    expect(labelFor(tag)).toBe(EXPECTED[tag]);
  });

  it.each(TAGS)("names the %s verdict's label in the comment footer", (tag) => {
    expect(footerFor(tag)).toContain(`\`${EXPECTED[tag]}\``);
  });
});

import { describe, expect, it } from "vitest";
import { vercel } from "./vercel.js";

describe("vercel()", () => {
  it("returns a SandboxProvider with tag 'isolated' and name 'vercel'", () => {
    const provider = vercel();
    expect(provider.tag).toBe("isolated");
    expect(provider.name).toBe("vercel");
  });

  it("has a create function", () => {
    const provider = vercel();
    expect(typeof provider.create).toBe("function");
  });

  it("accepts a token option", () => {
    // Should not throw
    const provider = vercel({ token: "my-token" });
    expect(provider.tag).toBe("isolated");
  });

  it("passes through Vercel SDK options", () => {
    // Should not throw when arbitrary SDK options are provided
    const provider = vercel({
      template: "node-22",
      timeoutMs: 30_000,
    });
    expect(provider.tag).toBe("isolated");
  });

  it("accepts an env option", () => {
    const provider = vercel({ env: { VERCEL_VAR: "value" } });
    expect(provider.tag).toBe("isolated");
    expect(provider.env).toEqual({ VERCEL_VAR: "value" });
  });

  it("defaults env to empty object when not provided", () => {
    const provider = vercel();
    expect(provider.env).toEqual({});
  });
});

